1	import { useCallback, useEffect, useState } from 'react';
2	
3	import { type EarnParams } from '@suite/router';
4	import { type YieldDtoV2 } from '@suite-common/earn-stablecoin-api';
5	import { getNetwork, getNetworkDisplaySymbol } from '@suite-common/wallet-config';
6	import {
7	    type YieldFlowCompleteValue,
8	    type YieldWithdrawFlowType,
9	    getConvertedOutputTokenBalanceToInputTokenAmount,
10	} from '@suite-common/wallet-core';
11	import { type Account } from '@suite-common/wallet-types';
12	
13	import { type YieldFlowContextValues, useYieldFlow } from '../hooks/useYieldFlow';
14	
15	type UseYieldWithdrawProps = {
16	    account: Account;
17	    routeParams: EarnParams;
18	    vault: YieldDtoV2;
19	};
20	
21	export type YieldWithdrawContextValues = Omit<YieldFlowContextValues, 'flowType'> & {
22	    flowType: YieldWithdrawFlowType;
23	    completedInput: YieldFlowCompleteValue;
24	    completedOutput?: YieldFlowCompleteValue;
25	    toggleWithdrawFlowType: () => void;
26	    selectMaxWithdraw: () => void;
27	    isMaxWithdrawInfoVisible: boolean;
28	};
29	
30	export const useYieldWithdraw = ({
31	    account,
32	    routeParams,
33	    vault,
34	}: UseYieldWithdrawProps): YieldWithdrawContextValues | null => {
35	    const [flowType, setFlowType] = useState<YieldWithdrawFlowType>('withdraw');
36	    const [isMaxWithdrawSelectionPending, setIsMaxWithdrawSelectionPending] = useState(false);
37	    const [maxWithdrawInfoAmount, setMaxWithdrawInfoAmount] = useState<string | null>(null);
38	
39	    const flowResult = useYieldFlow({
40	        account,
41	        routeParams,
42	        vault,
43	        flowType,
44	    });
45	    const { token, receiptToken, depositedSharesAmount, setAmountInput, liveAmount, flow } =
46	        flowResult;
47	
48	    const toggleWithdrawFlowType = useCallback(() => {
49	        setIsMaxWithdrawSelectionPending(false);
50	        setMaxWithdrawInfoAmount(null);
51	        setFlowType(prev => (prev === 'redeem' ? 'withdraw' : 'redeem'));
52	    }, []);
53	
54	    const selectMaxWithdraw = useCallback(() => {
55	        if (flowType === 'redeem') {
56	            setAmountInput(depositedSharesAmount);
57	
58	            return;
59	        }
60	
61	        setIsMaxWithdrawSelectionPending(true);
62	        setFlowType('redeem');
63	    }, [depositedSharesAmount, flowType, setAmountInput]);
64	
65	    // The flow resets the form while switching units, so fill it only after redeem is ready.
66	    useEffect(() => {
67	        if (
68	            !isMaxWithdrawSelectionPending ||
69	            flowType !== 'redeem' ||
70	            flow.currentStep !== 'action'
71	        ) {
72	            return;
73	        }
74	
75	        setAmountInput(depositedSharesAmount);
76	        setMaxWithdrawInfoAmount(depositedSharesAmount);
77	        setIsMaxWithdrawSelectionPending(false);
78	    }, [
79	        depositedSharesAmount,
80	        flow.currentStep,
81	        flowType,
82	        isMaxWithdrawSelectionPending,
83	        setAmountInput,
84	    ]);
85	
86	    useEffect(() => {
87	        if (maxWithdrawInfoAmount !== null && liveAmount !== maxWithdrawInfoAmount) {
88	            setMaxWithdrawInfoAmount(null);
89	        }
90	    }, [liveAmount, maxWithdrawInfoAmount]);
91	
