11	import { type YieldDtoV2 } from '@suite-common/earn-stablecoin-api';
12	import {
13	    type YieldAllowanceStatus,
14	    type YieldApproveModalState,
15	    type YieldFlowDisplayToken,
16	    type YieldFlowFormValues,
17	    type YieldFlowStepId,
18	    type YieldFlowToken,
