51	} from '../yieldFlowUtils';
52	
53	type UseYieldFlowProps = {
54	    account: Account;
55	    routeParams: EarnParams;
56	    vault: YieldDtoV2;
57	    flowType: YieldPositionFlowType;
58	};
59	
60	type UseYieldFlowStepsResult = {
61	    currentStep: YieldFlowStepId;
62	    isWrappedNativeVault: boolean;
63	};
64	
65	export type UseYieldFlowResult = {
66	    account: Account;
67	    vault: YieldDtoV2;
68	    token: YieldFlowToken | null;
69	    receiptToken: YieldFlowDisplayToken | null;
70	    apy: number | null;
71	    depositedAmount: string;
72	    depositedSharesAmount: string;
73	    flowKey: string;
74	    maxAmount: string;
75	    flowType: YieldPositionFlowType;
76	    inputTokenSymbol: string;
77	    otherUnitTokenSymbol: string;
78	    canToggleWithdrawUnit: boolean;
79	    liveAmount: string;
80	    actionAmount: string | null;
81	    completedAmount: string;
82	    completedReceiptAmount: string;
83	    unwrappedAmount: string | null;
84	    wrappedAmount: string | null;
85	    errorMessage: TranslationKey | undefined;
86	    approveModalState: YieldApproveModalState | null;
87	    pendingTransaction: YieldPendingTransactionState | null;
88	    allowanceAmount: string;
89	    allowanceStatus: YieldAllowanceStatus;
90	    approvalAction: YieldApprovalAction;
91	    canRevokeAllowance: boolean;
92	    hasWrappedTokenBalance: boolean;
93	    isAmountEmpty: boolean;
94	    isAmountTooHigh: boolean;
95	    isAmountInvalidDecimals: boolean;
96	    isApprovalInsufficient: boolean;
97	    isSubmittingApprove: boolean;
98	    isSubmittingAction: boolean;
99	    setAmountInput: (amount: string) => void;
100	    submitWrap: () => void;
101	    skipWrap: () => void;
102	    returnToWrapStep: () => void;
103	    submitUnwrap: () => void;
104	    skipUnwrap: () => void;
105	    submitApprovalAction: () => void;
106	    skipApprove: () => void;
107	    submitAction: () => void;
108	    revokeAllowance: () => void;
109	    enterModifyApproval: () => void;
110	    handleApproveModalCancel: () => Promise<void>;
111	    handleApproveSuccessTxid: (txid: string) => void;
112	    openPendingTransaction: (txid: string) => void;
113	    retryInitAllowance: () => void;
114	    methods: UseFormReturn<YieldFlowFormValues>;
115	    flow: UseYieldFlowStepsResult;
116	};
117	
118	/** Context value type shared by both deposit and withdraw — non-null token/receiptToken/vault. */
119	export type YieldFlowContextValues = Omit<
120	    UseYieldFlowResult,
121	    'token' | 'receiptToken' | 'vault'
122	> & {
123	    token: YieldFlowToken;
124	    receiptToken: YieldFlowDisplayToken;
125	    vault: YieldDtoV2;
126	};
127	
128	export const useYieldFlow = ({
129	    account,
130	    routeParams,
131	    vault,
132	    flowType,
133	}: UseYieldFlowProps): UseYieldFlowResult => {
134	    const dispatch = useDispatch();
135	    const { analytics } = useServices(selectDesktopAnalyticsDep);
136	    const { device } = useDevice();
137	    const methods = useForm<YieldFlowFormValues>({
138	        mode: 'onChange',
139	        defaultValues: {
140	            amountInput: '',
141	        },
142	    });
143	    const methodsRef = useCurrentRef(methods);
144	    const initAllowancePromiseRef = useRef<{ abort: () => void } | null>(null);
145	    const unwrapDefaultAmountRef = useRef<string | null>(null);
146	
147	    const { token, receiptToken, apy, depositedAmount, depositedSharesAmount, flowKey } =
148	        useResolvedYieldFlowData({
149	            account,
150	            routeParams,
151	            vault,
152	        });
153	    const allowanceFlowDataRef = useCurrentRef({
154	        account,
155	        vault,
156	        token,
157	        receiptToken,
158	    });
159	
160	    const ensureDeviceSession = useEnsureYieldDeviceSession({ flowType, flowKey });
161	    const session = useSelector(state => selectStablecoinYieldSession(state, flowType, flowKey));
162	    const sessionRef = useCurrentRef(session);
163	
164	    const isWrappedNativeVault = isWrappedNativeToken(account.symbol, vault.token.address);
165	    const hasWrappedTokenBalance = isAmountGreaterThan({
166	        amount: token?.balance ?? '0',
167	        threshold: '0',
168	    });
169	    const hasWrappedTokenBalanceRef = useCurrentRef(hasWrappedTokenBalance);
170	
171	    const isSharesInput = flowType === 'redeem';
172	    const canToggleWithdrawUnit = isYieldWithdrawFlow(flowType) && !!token && !!receiptToken;
173	
174	    const getMaxAmount = () => {
175	        if (flowType === 'deposit') {
176	            if (session.step === 'wrap') {
177	                // Max leaves the gas reserve aside; the field still shows the full balance and the
178	                // user may wrap up to it (see `amountTooHighThreshold`), with a recommendation.
179	                return getWrappableNativeBalance(account.formattedBalance);
180	            }
181	
182	            return token?.balance ?? '';
183	        }
184	        if (session.step === 'unwrap') {
185	            return token?.balance ?? '';
186	        }
187	        if (isSharesInput) {
188	            return depositedSharesAmount;
189	        }
190	
191	        return depositedAmount;
192	    };
193	    const maxAmount = getMaxAmount();
194	
195	    const inputTokenSymbol = isSharesInput ? (receiptToken?.symbol ?? '') : (token?.symbol ?? '');
196	    const otherUnitTokenSymbol = isSharesInput
197	        ? (token?.symbol ?? '')
198	        : (receiptToken?.symbol ?? '');
199	
200	    useEffect(() => {
201	        if (!flowKey) {
202	            return;
203	        }
204	
205	        dispatch(stablecoinYieldActions.initSession({ flowType, flowKey, isWrappedNativeVault }));
206	        dispatch(stablecoinYieldActions.resetSession({ flowType, flowKey, isWrappedNativeVault }));
207	
208	        if (flowType === 'deposit' && isWrappedNativeVault && hasWrappedTokenBalanceRef.current) {
209	            dispatch(
210	                stablecoinYieldActions.resolveWrappedNativeStep({
211	                    flowType,
212	                    flowKey,
213	                    step: 'wrap',
214	                }),
215	            );
216	        }
217	
218	        methodsRef.current.reset({ amountInput: '' });
219	
220	        return () => {
221	            dispatch(stablecoinYieldActions.disposeSession({ flowType, flowKey }));
222	        };
223	    }, [flowKey, flowType, dispatch, isWrappedNativeVault, hasWrappedTokenBalanceRef, methodsRef]);
224	
225	    const { allowanceStatus } = session.approval;
226	
227	    useEffect(
228	        () => () => {
229	            initAllowancePromiseRef.current?.abort();
230	            initAllowancePromiseRef.current = null;
231	        },
232	        [flowKey],
233	    );
234	
235	    const runInitAllowance = useCallback(() => {
236	        if (flowType !== 'deposit') {
237	            return;
238	        }
239	
240	        const {
241	            account: currentAccount,
242	            vault: currentVault,
243	            token: currentToken,
244	            receiptToken: currentReceiptToken,
245	        } = allowanceFlowDataRef.current;
246	
247	        if (!currentToken || !currentReceiptToken || !currentVault) {
248	            return;
249	        }
250	
251	        const promise = dispatch(
252	            initYieldAllowanceThunk({
253	                flowKey,
254	                flowType,
255	                flowData: {
256	                    account: currentAccount,
257	                    vault: currentVault,
258	                    token: currentToken,
259	                    receiptToken: currentReceiptToken,
260	                },
261	            }),
262	        );
263	
264	        initAllowancePromiseRef.current = promise;
265	        void promise
266	            .unwrap()
267	            .catch(() => {
268	                analytics.report({
269	                    type: events.yieldInteractionEvent.name,
270	                    payload: {
271	                        element: 'allowance-error-banner',
272	                        networkSymbol: currentToken.networkSymbol,
273	                        vaultId: currentVault.id,
274	                    },
275	                });
276	            })
277	            .finally(() => {
278	                if (initAllowancePromiseRef.current === promise) {
279	                    initAllowancePromiseRef.current = null;
280	                }
281	            });
282	    }, [allowanceFlowDataRef, analytics, dispatch, flowKey, flowType]);
283	
284	    useEffect(() => {
285	        const canInitializeAllowance =
286	            !isWrappedNativeVault || (session.isWrappedNativeVault && session.step === 'approve');
287	
288	        if (allowanceStatus !== 'idle' || !canInitializeAllowance) {
289	            return;
290	        }
291	        runInitAllowance();
292	    }, [
293	        allowanceStatus,
294	        isWrappedNativeVault,
295	        runInitAllowance,
296	        session.isWrappedNativeVault,
297	        session.step,
298	    ]);
299	
300	    useYieldPendingTransactionTracking({
301	        account,
302	        flowType,
303	        flowKey,
304	        vault,
305	    });
306	
307	    // Sync form value on step transitions driven by Redux (e.g. completeApproval, enterModifyMode from thunk)
308	    const prevStepRef = useRef<YieldFlowStepId | null>(null);
309	
310	    useEffect(() => {
311	        const prevStep = prevStepRef.current;
312	        const nextStep = session.step;
313	
314	        if (prevStep !== null && prevStep !== nextStep) {
315	            if (prevStep === 'wrap' && nextStep === 'approve') {
316	                methodsRef.current.reset({ amountInput: session.action.amount ?? '' });
317	            }
318	
319	            if (nextStep === 'wrap') {
320	                methodsRef.current.reset({ amountInput: '' });
321	            }
322	
323	            if (prevStep === 'approve' && nextStep === 'action') {
324	                const actionAmount = session.action.amount ?? '';
325	                const cappedAmount = isAmountGreaterThan({
326	                    amount: actionAmount,
327	                    threshold: maxAmount,
328	                })
329	                    ? maxAmount
330	                    : actionAmount;
331	                methodsRef.current.reset({
332	                    amountInput: cappedAmount,
333	                });
334	            }
335	
336	            if (prevStep === 'action' && nextStep === 'approve') {
337	                methodsRef.current.reset({
338	                    amountInput: getYieldModifyAmountInput({
339	                        liveAmount: methodsRef.current.getValues('amountInput'),
340	                        actionAmount: session.action.amount,
341	                        maxAmount,
342	                    }),
343	                });
344	            }
345	        }
346	
347	        prevStepRef.current = nextStep;
348	    }, [session.step, session.action.amount, methodsRef, maxAmount]);
349	
350	    useEffect(() => {
351	        if (session.step !== 'unwrap') {
352	            unwrapDefaultAmountRef.current = null;
353	
354	            return;
355	        }
356	
357	        const nextDefaultAmount = token?.balance ?? '';
358	        const currentAmount = methodsRef.current.getValues('amountInput');
359	
360	        if (
361	            unwrapDefaultAmountRef.current === null ||
362	            currentAmount === unwrapDefaultAmountRef.current
363	        ) {
364	            methodsRef.current.reset({ amountInput: nextDefaultAmount });
365	        }
366	
367	        unwrapDefaultAmountRef.current = nextDefaultAmount;
368	    }, [methodsRef, session.step, token?.balance]);
369	
370	    const flow = useMemo(
371	        () => ({ currentStep: session.step, isWrappedNativeVault }),
372	        [session.step, isWrappedNativeVault],
373	    );
374	
375	    const openPendingTransaction = useCallback(
376	        (txid: string) => {
377	            const pendingTxType = sessionRef.current.action.pendingTransaction?.type;
378	            if (pendingTxType) {
379	                analytics.report({
380	                    type: events.yieldInteractionEvent.name,
381	                    payload: {
382	                        element: 'pending-tx-open',
383	                        value: pendingTxType,
384	                        networkSymbol: account.symbol,
385	                        vaultId: vault.id,
386	                    },
387	                });
388	            }
389	
390	            dispatch(
391	                openModal({
392	                    type: 'transaction-detail',
393	                    txid,
394	                    descriptor: account.descriptor,
395	                    symbol: account.symbol,
396	                    deviceState: account.deviceState,
397	                    flow: 'detail',
398	                }),
399	            );
400	        },
401	        [account, analytics, dispatch, vault.id, sessionRef],
402	    );
403	
404	    const enterModifyApproval = useCallback(() => {
405	        dispatch(stablecoinYieldActions.enterModifyMode({ flowType, flowKey }));
406	    }, [dispatch, flowType, flowKey]);
407	
408	    const setAmountInput = useCallback(
409	        (amount: string) => {
410	            methodsRef.current.setValue('amountInput', amount);
411	        },
412	        [methodsRef],
413	    );
414	
415	    const openDeviceConnectionModal = useCallback(() => {
416	        if (device?.descriptor?.apiType === 'bluetooth') {
417	            dispatch(setConnectionMode('bluetooth'));
418	        }
419	        dispatch(setConnectionModal(true));
420	    }, [device, dispatch]);
421	
422	    const isDeviceConnected = !!device?.connected && !!device?.available;
423	
424	    const resolveWrappedNativeStep = useCallback(
425	        (step: 'wrap' | 'unwrap') => {
426	            dispatch(
427	                stablecoinYieldActions.resolveWrappedNativeStep({
428	                    flowType,
429	                    flowKey,
430	                    step,
431	                }),
432	            );
433	        },
434	        [dispatch, flowKey, flowType],
435	    );
