437	    const submitWrappedNative = useCallback(
438	        async (step: 'wrap' | 'unwrap') => {
439	            if (
440	                (step === 'wrap' && flowType !== 'deposit') ||
441	                (step === 'unwrap' && !isYieldWithdrawFlow(flowType))
442	            ) {
443	                return;
444	            }
445	
446	            if (!isDeviceConnected) {
447	                openDeviceConnectionModal();
448	
449	                return;
450	            }
451	
452	            if (!token?.contractAddress) {
453	                dispatch(
454	                    stablecoinYieldActions.setError({
