456	                        flowKey,
457	                        error: 'TR_EARN_YIELD_ERROR_GENERIC',
458	                    }),
459	                );
460	
461	                return;
462	            }
463	
464	            const amount = methodsRef.current.getValues('amountInput');
465	
466	            if (!isAmountGreaterThan({ amount, threshold: '0' })) {
467	                resolveWrappedNativeStep(step);
468	
469	                return;
470	            }
471	
472	            const isSessionReady = await ensureDeviceSession();
473	
474	            if (!isSessionReady) {
475	                return;
476	            }
477	
478	            const wrappedToken = {
479	                ...token,
480	                contractAddress: token.contractAddress,
481	            };
482	
483	            dispatch(stablecoinYieldActions.startSubmittingWrappedNative({ flowType, flowKey }));
484	            try {
485	                let txid: string | undefined;
486	
487	                if (step === 'wrap') {
488	                    const result = await dispatch(
489	                        submitWrapNativeTokenThunk({
490	                            account,
491	                            token: wrappedToken,
492	                            wrapAmount: amount,
493	                            yieldFlow: { flowType: 'deposit', flowKey },
494	                        }),
495	                    ).unwrap();
496	                    txid = result?.txid;
497	                } else if (isYieldWithdrawFlow(flowType)) {
498	                    const result = await dispatch(
499	                        submitUnwrapNativeTokenThunk({
500	                            account,
501	                            token: wrappedToken,
502	                            unwrapAmount: amount,
503	                            yieldFlow: { flowType, flowKey },
504	                        }),
505	                    ).unwrap();
506	                    txid = result?.txid;
507	                }
508	
509	                if (txid) {
510	                    dispatch(
511	                        stablecoinYieldActions.setPendingTx({
512	                            flowType,
513	                            flowKey,
514	                            tx: {
515	                                type: step,
516	                                txid,
517	                                amount,
518	                            },
519	                        }),
520	                    );
521	                }
522	            } catch {
523	                // The thunk handles compose/sign/broadcast failures itself (toast); this guards an
524	                // unexpected throw around it so the step surfaces an error instead of silently
525	                // rejecting. The step stays put, so the user can retry.
526	                dispatch(
527	                    stablecoinYieldActions.setError({
528	                        flowType,
529	                        flowKey,
530	                        error: 'TR_EARN_YIELD_ERROR_GENERIC',
531	                    }),
532	                );
533	            } finally {
534	                dispatch(stablecoinYieldActions.finishSubmittingAction({ flowType, flowKey }));
535	            }
536	        },
537	        [
538	            account,
539	            dispatch,
540	            ensureDeviceSession,
541	            flowKey,
542	            flowType,
543	            isDeviceConnected,
544	            methodsRef,
545	            openDeviceConnectionModal,
546	            resolveWrappedNativeStep,
547	            token,
548	        ],
549	    );
550	
