    // unwrapped or converted from shares), fall back to the amount as entered so the "Received"
    // side is never left blank. Both sides are always shown, so the screen transparently reflects
    // what was sent and what was received regardless of how the amount was entered or unwrapped.
    const receivedValue = output ?? input;

    return (
        <YieldFlowComplete
            type="withdraw"
            heading={<Translation id="TR_EARN_YIELD_WITHDRAW_COMPLETE" />}
            description={
                <Translation
                    id="TR_EARN_YIELD_WITHDRAW_COMPLETE_DESCRIPTION"
                    values={{ displaySymbol: receivedValue.token.symbol }}
                />
            }
            vaultId={vaultId}
            showFeedback
        >
            <YieldFlowTransferRow
                inputLabelId="TR_EARN_YIELD_AMOUNT_TO_WITHDRAW"
                outputLabelId="TR_RECEIVED"
                input={input}
                output={receivedValue}
            />
        </YieldFlowComplete>
    );
};
